// === Tab: mySketch ===
let currentMaxSides = 3; // 現在表示している最大角数（最初は三角形）
let direction = 1; // 増加（1）または減少（-1）を表す
let edgeLength; // 各図形の辺の長さ
let rotationAngle = 0; // 全体の回転角度
let triangleHue = 0; // 三角形の色相（HSB）

function setup() {
  createCanvas(windowWidth, windowHeight); // ウィンドウサイズに合わせてキャンバスを作成
  angleMode(DEGREES); // 角度を度数法で扱う
  colorMode(HSB, 360, 100, 100, 100); // 色をHSBで指定（色相、彩度、明度、透明度）
  edgeLength = max(width, height) / 20; // 辺の長さは画面の小さい方に基づく
  triangleHue = random(360); // 三角形の色相をランダムに設定
}

function draw() {
  background(0); // 背景を黒で塗りつぶす

  let maxSides = int(max(width, height) / 15); // 最大の角数（画面サイズに比例）

  stroke(255,50); // 線の色を白に設定
  strokeWeight(1); // 線の太さを細く設定

  // --- 回転アニメーション制御 ---
  if (direction === 1) {
    rotationAngle -= 0.2; // 増加中は左回転（ゆっくり）
  } else {
    rotationAngle += 0.4; // 減少中は右回転（早く）
  }

  push(); // 現在の描画状態を保存
  translate(width / 2, height / 2); // 原点を画面中央に移動
  rotate(rotationAngle); // 現在の回転角度を適用
  translate(-width / 2, -height / 2); // 描画基準点を元に戻す

  // --- 三角形の塗り設定（鮮やかな色） ---
  fill(triangleHue, 100, 100, 4); // HSBで彩度100・明度100・透明度4%

  // --- 正三角形を描画し、その頂点を取得 ---
  let triangleVertices = drawEquilateralTriangle(width / 2, height / 2, edgeLength);
  let sharedEdgeStart = triangleVertices[2]; // 次の図形に渡す始点
  let sharedEdgeEnd = triangleVertices[0]; // 次の図形に渡す終点

  // --- 正四角形から currentMaxSides まで描画 ---
  for (let sides = 4; sides <= currentMaxSides; sides++) {
    let brightness = map(sides, 4, maxSides, 90, 90); // 明度は固定（将来減衰させてもOK）
    fill(triangleHue, 100, brightness, 4); // 三角形の色相をベースに塗り設定

    let vertices = drawPolygonFromEdge(sharedEdgeStart, sharedEdgeEnd, edgeLength, sides); // 多角形を描画
    sharedEdgeStart = vertices[vertices.length - 1]; // 次の始点を更新
    sharedEdgeEnd = vertices[0]; // 次の終点を更新
  }

  pop(); // 描画状態を元に戻す

  // --- フェーズの更新処理（成長と縮小の繰り返し） ---
  if (frameCount % 5 === 0) { // 5フレームごとに更新
    currentMaxSides += direction; // 角数を1増減

    if (currentMaxSides >= maxSides) {
      direction = -1; // 最大に達したら減少モードに切り替え
    } else if (currentMaxSides <= 3) {
      direction = 1; // 三角形に戻ったら増加モードに戻す
      triangleHue = random(360); // 三角形の色相を新たにランダムで決定
    }
  }
}

/**
 * 正三角形を描画し、3つの頂点を配列で返す
 */
function drawEquilateralTriangle(x, y, edgeLength) {
  let h = (sqrt(3) / 2) * edgeLength; // 正三角形の高さを計算

  let v1 = { x: x - edgeLength / 2, y: y + h / 2 }; // 左下の頂点
  let v2 = { x: x + edgeLength / 2, y: y + h / 2 }; // 右下の頂点
  let v3 = { x: x, y: y - h / 2 }; // 上の頂点

  beginShape(); // 図形の描画開始
  vertex(v1.x, v1.y);
  vertex(v2.x, v2.y);
  vertex(v3.x, v3.y);
  endShape(CLOSE); // 図形の描画終了（閉じる）

  return [v1, v2, v3]; // 頂点配列を返す
}

/**
 * 指定された辺から出発し、正多角形を描画して頂点配列を返す
 */
function drawPolygonFromEdge(e, d, edgeLength, sides) {
  let angleED = atan2(d.y - e.y, d.x - e.x); // 指定辺の角度を計算
  var vertices = []; // 頂点リスト初期化
  let currentX = e.x;
  let currentY = e.y;
  vertices.push({ x: e.x, y: e.y }); // 始点を追加

  let angleStep = -360 / sides; // 頂点ごとの角度（反時計回り）

  for (let i = 0; i < sides - 1; i++) { // 残りの頂点を計算
    let angle = angleED + angleStep * i;
    let nextX = currentX + edgeLength * cos(angle);
    let nextY = currentY + edgeLength * sin(angle);
    vertices.push({ x: nextX, y: nextY });
    currentX = nextX;
    currentY = nextY;
  }

  beginShape(); // 多角形の描画開始
  for (let v of vertices) {
    vertex(v.x, v.y);
  }
  endShape(CLOSE); // 図形を閉じる

  return vertices; // 頂点配列を返す
}
